#!/usr/bin/env node
/**
 * Generates `daemon/internal/catalog/geo_data.go` from the committed
 * `dashboard/src/assets/geo/cn-cities.json`.
 *
 * The daemon filters the catalog by province/city and computes the map's
 * aggregates server-side. Both sides must agree on the label -> city mapping,
 * so the dashboard asset stays the single source and this file is generated
 * from it. `--check` fails when the generated file drifts from the asset.
 *
 * Usage: node scripts/geo/gen-daemon-geo.mjs [--check]
 */
import { readFile, writeFile } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..')
const ASSET = join(ROOT, 'dashboard', 'src', 'assets', 'geo', 'cn-cities.json')
const OUT = join(ROOT, 'daemon', 'internal', 'catalog', 'geo_data.go')

function render(cities) {
  const entries = new Map()
  for (const city of cities) {
    entries.set(city.name, city)
    for (const alias of city.aliases ?? []) entries.set(alias, city)
  }
  const keys = [...entries.keys()].sort((left, right) => (left < right ? -1 : left > right ? 1 : 0))
  // Match gofmt's tabwriter alignment (one space of padding after the longest
  // `"key":` cell) so the generated file is stable without a gofmt pass.
  const cells = keys.map((key) => `${JSON.stringify(key)}:`)
  const width = Math.max(...cells.map((cell) => [...cell].length))
  const lines = keys.map((key, index) => {
    const padding = ' '.repeat(width - [...cells[index]].length + 1)
    const city = entries.get(key)
    return `\t${cells[index]}${padding}{Code: ${JSON.stringify(city.code)}, ProvinceCode: ${JSON.stringify(city.provinceCode)}},`
  })
  return [
    '// Code generated by scripts/geo/gen-daemon-geo.mjs from',
    '// dashboard/src/assets/geo/cn-cities.json; DO NOT EDIT.',
    '',
    'package catalog',
    '',
    '// cityIndex maps every vendor city label (and its aliases) to the GB/T 2260',
    '// city and province codes the catalog filters use.',
    'var cityIndex = map[string]City{',
    ...lines,
    '}',
    '',
  ].join('\n')
}

async function main() {
  const check = process.argv.includes('--check')
  const asset = JSON.parse(await readFile(ASSET, 'utf8'))
  const expected = render(asset.cities)
  if (check) {
    const actual = await readFile(OUT, 'utf8').catch(() => '')
    if (actual !== expected) {
      console.error(`drift: ${OUT}`)
      process.exitCode = 1
    }
    return
  }
  await writeFile(OUT, expected)
  console.log(`${OUT}: ${Buffer.byteLength(expected)} bytes`)
}

await main()
